                </div>
                <div class="log_title">
                    {{$t('register')}}
                </div>
                <div class="log_desc">
                    {{$t('registration_requirement')}}
                </div>
                <div class="reg_tab">
                    <button :class="{'active':is_active==='phone_number'}" @click="is_active='phone_number'">
                        Telefon raqam
                    </button>
                    <button :class="{'active':is_active==='email'}" @click="is_active='email'">
                        Pochta
                    </button>
                </div>
                <div class="tab_1" v-if="is_active==='phone_number'">
                    <form  @submit.prevent="registerUser">
                        <div class="phone_input">
                            <label>{{$t('enter_phone')}}</label>
                            <div>
                                <input type="text" v-model="phone_number" placeholder="+998900000000">
                            </div>
                          <label>Username</label>
                          <div>
                            <input type="text" v-model="username" placeholder="username">
                          </div>
                        </div>
                        <div class="router_reg">
                            <button>
                                <b-spinner v-if="show_spinner" variant="white" ></b-spinner>
                                <span v-if="!show_spinner">{{$t('continue')}}</span>
                            </button>
                        </div>
                    </form>
                </div>
                <div class="tab_1" v-if="is_active==='email'">
                    <form  @submit.prevent="registerUser1">
                        <div class="phone_input">
                            <label>{{$t('enter_postal_address')}}</label>
                            <div>
                                <input v-model="email" type="text" placeholder="user@gmail.com">
                            </div>
                          <label>Username</label>
                          <div>
                            <input type="text" v-model="username" placeholder="username">
                          </div>
                        </div>
                        <div class="router_reg">
                            <button>
                                <b-spinner v-if="show_spinner" variant="white" ></b-spinner>
                                <span v-if="!show_spinner">{{$t('continue')}}</span>
                            </button>
                        </div>
                    </form>
                </div>
            </div>


        </section>
        <Footer></Footer>

    </div>
</template>
<script>
    import Footer from '../components/Footer.vue'
    export default {
        components:{
            Footer
        },
        data(){
            return {

              isPasswordVisible: false,
                is_active:'phone_number',
                item1:'',
                item2:'',
                item3:'',
                item4:'',
                is_code:false,
                phone_number:'+998',
                email:'',
                username:'',
                show_code:false,
                show_spinner:false,
                username_main:'',
                password:'',
                user_id:'',
                is_username:false
            }
        },
        mounted() {

        },
      computed: {
        passwordFieldType() {
          return this.isPasswordVisible ? 'text' : 'password';
        },
        passwordIcon() {
          return this.isPasswordVisible ? 'eye-slash' : 'eye';
        }
      },
      methods:{
        togglePasswordVisibility() {
          this.isPasswordVisible = !this.isPasswordVisible;
        },

        moveFocus(event, nextFieldId) {
                if (event.target.value.length === 1 && nextFieldId) {
                    document.getElementById(nextFieldId).focus();
                }
            },
            myFunction(){
                if(this.item1<0||this.item1>9){
                    this.item1=''
                }
            },
            myFunction1(){
                if(this.item2<0||this.item2>9){
                    this.item2=''
                }
            },
            myFunction2(){
                if(this.item3<0||this.item3>9){
                    this.item3=''
                }
            },
            myFunction3(){
                if(this.item4<0||this.item4>9){
                    this.item4=''
                }
            },
        registerUser() {
            this.show_spinner=true
            this.$axios.post('/account/register/', {
                "phone_number":this.phone_number,
                "username":this.username,
                "user_type":this.$route.params.user_type,
                "auth_type":this.is_active
            })
            .then(()=>{
                this.show_spinner=false
                this.show_code=true
            })

            .catch(error=>{
                this.show_code=false
                this.show_spinner=false
              console.log(error.response.data.error)
                this.$toast(`${error.response.data.error}`, {
                    timeout: 2000,
                    type:"error"
                });
            })
          },
            registerUser1() {
              this.show_spinner=true
              this.$axios.post('/account/register/', {
                  "email":this.email,
                  "username":this.username,
                  "user_type":this.$route.params.user_type,
                  "auth_type":this.is_active
              })
                  .then(()=>{
                      this.show_spinner=false
                      this.show_code=true
                  })
                  .catch(error=>{
                    console.log(error)
                      this.show_code=false
                      this.show_spinner=false
                    this.$toast(`${error.response.data.error}`, {
                      timeout: 2000,
                      type:"error"
                    });

                  })
          },
            isCodeActive1() {
                this.show_spinner=true
                this.$axios.post('/account/verify/', {
                    "phone_number":this.phone_number,
                    "code": `${this.item1}`+this.item2+this.item3+this.item4,
                    "user_type":this.$route.params.user_type,
                    "auth_type":this.is_active
                })
                    .then(res=>{
                        console.log(res.data)
                        this.user_id=res.data.user_id
                        this.show_spinner=false
                        this.is_username=true
                    })
                    .catch(error=>{
                        this.show_spinner=false
                        this.$toast(`${error.response.data.error}`, {
                            timeout: 2000,
                            type:"error"
                        });
                    })

            },
            isCodeActive2() {
                this.show_spinner=true
                this.$axios.post('/account/verify/', {
                    "email":this.email,
                    "code":`${this.item1}`+this.item2+this.item3+this.item4,
                    "user_type":this.$route.params.user_type,
                    "auth_type":this.is_active
                })
                    .then(res=>{
                        this.show_spinner=false
                        console.log(res.data)
                        this.user_id=res.data.user_id
                        this.show_spinner=false
                        this.is_username=true
                    })
                    .catch(error=>{
                        this.show_spinner=false
                        this.$toast(`${error.response.data.error}`, {
                            timeout: 2000,
                            type:"error"
                        });
                    })

            },
            SetInfo(){
                this.$axios.post('/account/set-info-password/', {
                    "full_name":this.username_main,
                    "password":this.password,
                    "id":this.user_id,
                })
                .then(res=>{
                    localStorage.setItem("token",res.data.password)
                    this.$router.push(`/login/${this.$route.params.user_type}`)
                })
                .catch(error=>{
                    this.show_code=false
                    this.show_spinner=false
                    this.$toast(`${error.response.data.error}`, {
                        timeout: 2000,
                        type:"error"
                    });
                })
            }
        }

    }
</script>