<template>
  <div class="test_bg">
    <div class="container">
      <h2 class="text-center mt-5 mb-2">
        {{news.title}}
      </h2>
      <div v-html="news.description">
        
      </div>
      <img width="100%" class="mb-5" :src="news.cover_image" alt="">
    </div>
    <Footer></Footer>
  </div>
</template>
<script>
import Footer from "../components/Footer";

export default {
  components: {
    Footer
  },
  data(){
    return{
      news:[]
    }
  },
  mounted() {
    this.$axios.get(`/news/${this.$route.params.id}/`, {
      headers: {
        'Accept-Language':localStorage.getItem('lang')
      }
    })
        .then(res => {
          this.news = res.data

        })
  },
}
</script>